        { from: 'E10', to: 'E11', title: '猎头者家庭记忆与契约', dir: '小小不肯走，两个巨大头颅靠近审视', loc: '倒吊塔废墟', urgency: '中', deadline: '当场' },
        { from: 'E11', to: 'E12', title: '师徒归来与阶段收束', dir: '巷外传来熟悉的沉重脚步与丝线反光', loc: '血锯药剂店门外', urgency: '中', deadline: '即将' },
      ];

      function findReadyPair(events) {
        const anchors = events.锚点状态 ?? {};
        for (const pair of BRIDGE_PAIRS) {
          const from = anchors[pair.from] ?? {};
          const fromState = from.状态;
          const toState = anchors[pair.to]?.状态;
          const wrappedUp = fromState === '完成' || fromState === '变形' || fromState === '取消'
            || (fromState === '活跃' && from.收尾 === true);
          if (wrappedUp && toState === '未触发') return pair;
        }
        return null;
      }

      const root = document.currentScript?.closest('.wa-panel') ?? document.querySelector('.wa-panel');
      if (!root) return;
      const byId = id => root.querySelector(`#${id}`);
      const text = (id, value) => { const node = byId(id); if (node) node.textContent = value ?? '无'; };
      const asArray = value => Array.isArray(value) ? value : [];
      const clamp = value => Math.max(0, Math.min(100, Number(value) || 0));

      function updateAdvanceButton(events) {
        const btn = byId('wa-advance-btn');
        if (!btn) return;
        const pair = findReadyPair(events);
        const omenId = events.近期预兆?.事件ID;
        if (pair) {
          btn.disabled = !mvuAvailable;
          btn.textContent = `推进：${pair.to} ${pair.title}`;
          btn.title = '手动确认推进：把下一事件写入预兆，预兆正文由叙事者下一轮描写。';
        } else if (omenId) {
          btn.disabled = true;
          btn.textContent = `已进入预兆：${omenId}`;
          btn.title = '';
        } else {
          btn.disabled = true;
          btn.textContent = '当前无可推进事件';
          btn.title = '';
        }
      }

      function renderList(node, items, emptyText = '暂无') {
        node.replaceChildren();
        const values = asArray(items);
        if (!values.length) {
          const li = document.createElement('li');
          li.textContent = emptyText;
          li.className = 'wa-muted';
          node.append(li);
          return;
        }
        for (const item of values) {
          const li = document.createElement('li');
          li.textContent = String(item);
          node.append(li);
        }
      }

      function relationWord(value, positive = true) {
        const score = clamp(value);
        if (!positive) {
          if (score >= 65) return '高度';
          if (score >= 30) return '明显';
          if (score > 0) return '轻微';
          return '无';
        }
        if (score >= 65) return '深厚';
        if (score >= 30) return '稳定';
        if (score > 0) return '初步';
        if (score <= -30) return '破裂';
        if (score < 0) return '疏离';
        return '未建立';
      }

      function makeMeter(label, value, negative = false) {
        const score = clamp(value);
        const row = document.createElement('div');
        row.className = 'wa-meter-row';
        const name = document.createElement('span');
        name.textContent = label;
        const track = document.createElement('span');
        track.className = 'wa-meter';
        const fill = document.createElement('span');
        fill.dataset.negative = String(negative);
        fill.style.left = '0%';
        fill.style.width = `${score}%`;
        track.append(fill);
        const words = document.createElement('span');
        words.className = 'wa-meter-text';
        words.textContent = `${score} · ${relationWord(Math.abs(score), negative)}`;
        row.append(name, track, words);
        return row;
      }

      function renderRelations(relations) {
        const container = byId('wa-relations');
        container.replaceChildren();
        const unlocked = Object.entries(relations ?? {}).filter(([, relation]) => relation?.解锁);
        if (!unlocked.length) {
          const empty = document.createElement('p');
          empty.className = 'wa-muted';
          empty.textContent = '尚无人物解锁。';
          container.append(empty);
          return;
        }
        for (const [name, relation] of unlocked) {
          const details = document.createElement('details');
          details.className = 'wa-person';
          const summary = document.createElement('summary');
          const heading = document.createElement('span');
          heading.className = 'wa-name';
          heading.textContent = name;
          const status = document.createElement('span');
          status.className = 'wa-status';
          status.textContent = `${relation.生存状态 ?? '状态未知'}${relation.在场 ? ' · 在场' : ''}`;
          summary.append(heading, status);

          const body = document.createElement('div');
          body.className = 'wa-person-body';
          const meta = document.createElement('p');
          meta.className = 'wa-person-meta';
          meta.textContent = `${relation.关系类型 ?? '关系未明'}｜${relation.人物阶段 ?? '阶段未明'}｜${relation.位置 ?? '位置未知'}`;
          const situation = document.createElement('p');
          situation.className = 'wa-value';
          situation.textContent = relation.处境 ?? '处境未知';
          const hasContact = relation.最近互动 && relation.最近互动 !== '无';
          if (hasContact) {
            body.append(meta, situation);
            body.append(
              makeMeter('好感', relation.好感),
              makeMeter('信赖', relation.信赖),
              makeMeter('戒备', relation.戒备, true),
              makeMeter('吸引', relation.吸引),
              makeMeter('创伤', relation.关系创伤, true),
              makeMeter('恶堕', relation.恶堕, true)
            );
            const cue = document.createElement('p');
            cue.className = 'wa-muted';
            cue.textContent = `最近互动：${relation.最近互动}`;
            body.append(cue);
          } else {
            const locked = document.createElement('p');
            locked.className = 'wa-muted';
            locked.textContent = '尚无实际接触，仅显示姓名与状态。';
            body.append(locked);
          }
          details.append(summary, body);
          container.append(details);
        }
      }

      function renderEdges(edges) {
        const container = byId('wa-edges');
        container.replaceChildren();
        const values = asArray(edges);
        if (!values.length) {
          const empty = document.createElement('p');
          empty.className = 'wa-muted';
          empty.textContent = '尚无需要长期记录的角色关系。';
          container.append(empty);
          return;
        }
        for (const edge of values) {
          const row = document.createElement('div');
          row.className = 'wa-edge';
          const title = document.createElement('p');
          title.className = 'wa-value';
          title.textContent = `${asArray(edge.双方).join(' ↔ ')}｜${edge.关系类型 ?? '关系未明'}`;
          const detail = document.createElement('p');
          detail.className = 'wa-value wa-muted';
          detail.textContent = `${edge.当前状态 ?? '状态未明'}｜${edge.公开程度 ?? '公开程度未明'}｜${edge.最近变化 ?? '暂无变化'}`;
          row.append(title, detail);
          container.append(row);
        }
      }

      function updateUrgency(card, urgency) {
        card.classList.toggle('wa-card--urgent', urgency === '高' || urgency === '极高');
      }

      function render(data) {
        const state = data?.stat_data;
        if (!state) throw new Error('当前楼层还没有初始化变量');
        const world = state.世界 ?? {};
        const linen = state.林恩 ?? {};
        const system = state.系统 ?? {};
        const events = state.事件 ?? {};
        const active = events.唯一活跃事件 ?? {};
        const omen = events.近期预兆 ?? {};

        text('wa-phase', `${world.阶段编号 ?? '未知'} · ${world.阶段名称 ?? '阶段未知'}`);
        text('wa-phase-progress', `${world.模糊阶段进度 ?? '进度未知'}｜${world.氛围 ?? '氛围未知'}`);
        text('wa-location', world.地点);
        text('wa-time', world.当前场景时间);
        text('wa-linen', `17岁｜${linen.身体状况 ?? '身体状况未知'}`);
        const identityBox = byId('wa-identities');
        identityBox.replaceChildren();
        for (const identity of asArray(linen.当前身份)) {
          const chip = document.createElement('span');
          chip.className = 'wa-chip';
          chip.textContent = identity;
          identityBox.append(chip);
        }
        text('wa-task', `${system.当前任务 ?? '无'}｜${system.任务状态 ?? '无'}`);
        text('wa-task-note', `${linen.当前明确目标 ?? '目标未明确'}｜${system.任务说明 ?? '无说明'}`);
        text('wa-current-event', `${active.事件ID || '无'} ${active.标题 || '暂无活跃事件'}｜${active.紧迫度 ?? '无'}`);
        text('wa-current-event-progress', `${active.地点 ?? '地点未知'}｜${active.模糊期限 ?? '期限未知'}｜${active.进展 ?? '暂无进展'}`);
        updateUrgency(byId('wa-current-event-card'), active.紧迫度);

        renderRelations(state.关系);
        renderEdges(state.角色关系);

        text('wa-event-title', `${active.事件ID || '无'} ${active.标题 || '暂无活跃事件'}｜${active.状态 ?? '无'}｜紧迫度 ${active.紧迫度 ?? '无'}`);
        text('wa-event-detail', `${active.地点 ?? '地点未知'}｜参与者：${asArray(active.参与者).join('、') || '未知'}｜${active.模糊期限 ?? '期限未知'}｜${active.进展 ?? '暂无进展'}`);
        updateUrgency(byId('wa-event-detail-card'), active.紧迫度);

        text('wa-omen-title', `${omen.事件ID || '无预兆'}｜${omen.紧迫度 ?? '无'}`);
        text('wa-omen-detail', `${omen.方向 ?? '暂无'}｜${omen.地点 ?? '地点未知'}｜${omen.模糊期限 ?? '期限未知'}`);
        updateAdvanceButton(events);
        renderList(
          byId('wa-results'),
          asArray(events.最近结果).slice(-3).reverse().map(item => `${item.事件ID || '原创'} ${item.标题}：${item.结果}`),
          '暂无事件结果'
        );

        text('wa-sys-task', `${system.当前任务 ?? '无'}｜${system.任务状态 ?? '无'}`);
        text('wa-sys-task-stage', system.任务阶段 ?? '');
        text('wa-sys-task-note', system.任务说明 ?? '');
        text('wa-sys-level', `等级 ${linen.等级 ?? 1}`);
        const skillBox = byId('wa-sys-skills');
        skillBox.replaceChildren();
        for (const skill of asArray(linen.技能)) {
          const chip = document.createElement('span');
          chip.className = 'wa-chip';
          chip.textContent = skill;
          skillBox.append(chip);
        }
        renderList(byId('wa-sys-codex'), [...asArray(system.图鉴), ...asArray(linen.图鉴已解锁)], '图鉴尚未收录条目');
        renderList(byId('wa-sys-achievements'), [...asArray(system.成就), ...asArray(linen.成就)], '尚无成就');
        const evilBox = byId('wa-sys-evil');
        evilBox.replaceChildren();
        const unlockedPeople = Object.entries(state.关系 ?? {}).filter(([, relation]) => relation?.解锁);
        if (!unlockedPeople.length) {
          const empty = document.createElement('p');
          empty.className = 'wa-muted';
          empty.textContent = '尚无已解锁人物。';
          evilBox.append(empty);
        } else {
          for (const [name, relation] of unlockedPeople) {
            evilBox.append(makeMeter(name, relation.恶堕 ?? 0, true));
          }
        }
        text('wa-sys-notice', system.最近提示 ?? '');
        text('wa-sys-event-notice', system.事件通知 ?? '');

        byId('wa-error').hidden = true;
      }

      function showError(error) {
        const node = byId('wa-error');
        node.textContent = `暂显示初始状态：MVU变量将在第一条回复保存后自动刷新。${error?.message ? `（${error.message}）` : ''}`;
        node.hidden = false;
      }

      function getHostWindows() {
        const hosts = [globalThis];
        for (const candidate of [globalThis.parent, globalThis.top]) {
          try {
            if (candidate && !hosts.includes(candidate)) hosts.push(candidate);
          } catch {
            // 跨域父页面不可访问时继续使用当前窗口。
          }
        }
        return hosts;
      }

      function findMvu() {
        for (const host of getHostWindows()) {
          try {
            if (host.Mvu?.getMvuData) return host.Mvu;
          } catch {
            // 某一层窗口不可访问时继续向上查找。
          }
        }
        return undefined;
      }

      function getMessageId() {
        if (typeof getCurrentMessageId === 'function') return getCurrentMessageId();
        const match = String(globalThis.name || '').match(/^TH-message--(\d+)--/);
        return match ? Number(match[1]) : 'latest';
      }

      function unwrapMessageVariables(message) {
        const variables = message?.variables;
        if (!variables) return undefined;
        if (Array.isArray(variables)) return variables[message?.swipe_id ?? 0] ?? variables.at(-1);
        if (variables.stat_data) return variables;
        return variables[message?.swipe_id ?? 0];
      }

      function readStoredVariables(messageId) {
        for (const host of getHostWindows()) {
          try {
            const tavern = host.SillyTavern;
            const context = typeof tavern?.getContext === 'function' ? tavern.getContext() : tavern;
            const chat = context?.chat;
            if (!Array.isArray(chat) || !chat.length) continue;
            const message = Number.isInteger(messageId) ? chat[messageId] : [...chat].reverse().find(item => !item?.is_system);
            let data = unwrapMessageVariables(message);
            if (!data?.stat_data) {
              for (let index = chat.length - 1; index >= 0; index -= 1) {
                data = unwrapMessageVariables(chat[index]);
                if (data?.stat_data) break;
              }
            }
            if (data?.stat_data) return data;
          } catch {
            // 当前宿主入口不可用时尝试下一层窗口。
          }
        }
        return undefined;
      }

      function readCurrent(mvu = findMvu()) {
        try {
          const messageId = getMessageId();
          let data = mvu?.getMvuData({ type: 'message', message_id: messageId });
          if (!data?.stat_data && mvu) data = mvu.getMvuData({ type: 'message', message_id: 'latest' });
          if (!data?.stat_data) data = readStoredVariables(messageId);
          if (!data?.stat_data) {
            render({ stat_data: FALLBACK_STATE });
            showError(new Error('首条消息尚无已保存变量'));
            return;
          }
          render(data);
          byId('wa-error').hidden = true;
        } catch (error) {
          render({ stat_data: FALLBACK_STATE });
          showError(error);
        }
      }

      async function advanceCurrentEvent() {
        const mvu = findMvu();
        if (!mvu) return;
        let data = null;
        try {
          const messageId = getMessageId();
          data = mvu.getMvuData({ type: 'message', message_id: messageId })
            || mvu.getMvuData({ type: 'message', message_id: 'latest' });
        } catch {
          // 读取失败时走消息变量回退。
        }
        if (!data?.stat_data) data = readStoredVariables(getMessageId());
        if (!data?.stat_data) return;
        const pair = findReadyPair(data.stat_data.事件 ?? {});
        if (!pair) return;
        const state = JSON.parse(JSON.stringify(data.stat_data));
        const events = state.事件;
        const fromAnchor = events.锚点状态[pair.from];
        if (fromAnchor.状态 === '活跃') fromAnchor.状态 = '完成';
        events.锚点状态[pair.to].状态 = '预兆';
        events.近期预兆 = {
          事件ID: pair.to,
          方向: pair.dir,
          地点: pair.loc,
          参与者: [],
          紧迫度: pair.urgency,
          模糊期限: pair.deadline,
        };
        const hasActive = Object.values(events.锚点状态).some(anchor => anchor.状态 === '活跃' || anchor.状态 === '变形');
        if (!hasActive) {
          events.唯一活跃事件 = {
            事件ID: '', 标题: '', 地点: '', 参与者: [], 状态: '无', 紧迫度: '无', 模糊期限: '无', 进展: '', 幕后停止点: '',
          };
        }
        state.系统 = state.系统 ?? {};
        state.系统.事件通知 = `${pair.to}已进入预兆：${pair.dir}`;
        try {
          const full = JSON.parse(JSON.stringify(data));
          full.stat_data = state;
          await mvu.replaceMvuData(full, { type: 'message', message_id: 'latest' });
        } catch (error) {
          const node = byId('wa-error');
          node.textContent = `推进失败：${error?.message ?? error}`;
          node.hidden = false;
          return;
        }
        readCurrent(mvu);
      }

      const tabs = [...root.querySelectorAll('[role="tab"]')];
      function activateTab(next) {
        for (const tab of tabs) {
          const selected = tab === next;
          tab.setAttribute('aria-selected', String(selected));
          tab.tabIndex = selected ? 0 : -1;
          byId(tab.getAttribute('aria-controls')).hidden = !selected;
        }
      }
      tabs.forEach((tab, index) => {
        tab.addEventListener('click', () => activateTab(tab));
        tab.addEventListener('keydown', event => {
          if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
          event.preventDefault();
          const offset = event.key === 'ArrowLeft' ? -1 : event.key === 'ArrowRight' ? 1 : 0;
          const nextIndex = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (index + offset + tabs.length) % tabs.length;
          tabs[nextIndex].focus();
          activateTab(tabs[nextIndex]);
        });
      });

      const subscriptions = [];
      async function bootstrap() {
        readCurrent();
        let mvu = findMvu();
        for (let attempt = 0; !mvu && attempt < 60; attempt += 1) {
          await new Promise(resolve => setTimeout(resolve, 250));
          mvu = findMvu();
        }
        if (!mvu) return;
        mvuAvailable = true;
        readCurrent(mvu);
        const advanceBtn = byId('wa-advance-btn');
        if (advanceBtn) advanceBtn.addEventListener('click', () => void advanceCurrentEvent());
        if (mvu.events && typeof eventOn === 'function') {
          const refresh = () => readCurrent(mvu);
          subscriptions.push(eventOn(mvu.events.VARIABLE_INITIALIZED, refresh));
          subscriptions.push(eventOn(mvu.events.VARIABLE_UPDATE_ENDED, refresh));
        }
      }
      window.addEventListener('pagehide', () => subscriptions.forEach(subscription => subscription?.stop?.()), { once: true });
      void bootstrap();
    })();
  </script>
