async function importFirstAvailable(urls) {
  let lastError;
  for (const url of urls) {
    try {
      await import(url);
      return;
    } catch (error) {
      lastError = error;
      console.warn(`[诡异药剂师v0.3.3.1] MVU 加载失败，尝试备用源：${url}`, error);
